function NeumorphicButton({ children, onPress, style, selecionado = false }: any) {
  const scale = React.useRef(new Animated.Value(1)).current;

  const handlePressIn = () => {
    Animated.spring(scale, { 
      toValue: 0.95, 
      useNativeDriver: true, 
      speed: 50, 
      bounciness: 0 
    }).start();
  };

  const handlePressOut = () => {
    Animated.spring(scale, { 
      toValue: 1, 
      useNativeDriver: true, 
      speed: 40, 
      bounciness: 4 
    }).start();
  };

  return (
    <TouchableWithoutFeedback onPressIn={handlePressIn} onPressOut={handlePressOut} onPress={onPress}>
      <Animated.View style={[{ transform: [{ scale }] }, style]}>
        {selecionado ? (
          <LinearGradient 
            colors={COR_BORDA_GRAD} 
            start={{x:0,y:0}} 
            end={{x:1,y:1}} 
            style={estilos.cardBordaGrad}
          >
            {children}
          </LinearGradient>
        ) : (
          children
        )}
      </Animated.View>
    </TouchableWithoutFeedback>
  );
}

export default function TelaInicio(): JSX.Element {
  const navegacao = useNavigation<NavegacaoPrincipal>();
  const { width } = useWindowDimensions();

  const [nomeUsuario, setNomeUsuario] = useState('');
  const [nomeEditando, setNomeEditando] = useState(false);
  const [nomeTemporario, setNomeTemporario] = useState('');
  const [fotoUri, setFotoUri] = useState<string | null>(null);
  const [onlineUids, setOnlineUids] = useState<string[]>([]);
  const [fotosPorUid, setFotosPorUid] = useState<{ [uid: string]: string }>({});
  const [novaEscalaCount, setNovaEscalaCount] = useState<number>(0);
  const [novaRepertorioCount, setNovaRepertorioCount] = useState<number>(0);
  const [novidadesCards, setNovidadesCards] = useState<Record<string, number>>({});
  const [nomeSelecionado, setNomeSelecionado] = useState<string | null>(null);
  const blinkOpacity = React.useRef(new Animated.Value(1)).current;
  const blinkOpacityRep = React.useRef(new Animated.Value(1)).current;
  const cardPulse = React.useRef(new Animated.Value(1)).current;
  const notifEscalaRef = React.useRef<string | null>(null);
  const notifRepRef = React.useRef<string | null>(null);

  useEffect(() => {
    async function carregarDados() {
      const nome = await AsyncStorage.getItem('nomeUsuario');
      const foto = await AsyncStorage.getItem('fotoUsuario');
      if (nome) {
        setNomeUsuario(nome);
        setNomeTemporario(nome);
      } else {
        setNomeTemporario('');
      }
      if (foto) setFotoUri(foto);
    }
    carregarDados();
  }, []);

  const salvarNome = async () => {
    const nomeFinal = nomeTemporario.trim();
    if (nomeFinal.length < 2) {
      Alert.alert('Aviso', 'Digite um nome com pelo menos 2 caracteres!');
      return;
    }
    setNomeUsuario(nomeFinal);
    setNomeEditando(false);
    await AsyncStorage.setItem('nomeUsuario', nomeFinal);
  };

  const cancelarEdicaoNome = () => {
    setNomeTemporario(nomeUsuario);
    setNomeEditando(false);
  };

  useFocusEffect(React.useCallback(() => {
    let mounted = true;
    const lerFlag = async () => {
      try {
        const v = await AsyncStorage.getItem('nova_escala');
        if (mounted) setNovaEscalaCount(v ? parseInt(v, 10) || 0 : 0);
      } catch (e) { console.log('Erro ao ler flag nova_escala', e); }
    };
    lerFlag();
    return () => { mounted = false; };
  }, []));

  useFocusEffect(React.useCallback(() => {
    let mounted = true;
    const lerFlagRep = async () => {
      try {
        const v = await AsyncStorage.getItem('nova_repertorio');
        if (mounted) setNovaRepertorioCount(v ? parseInt(v, 10) || 0 : 0);
      } catch (e) { console.log('Erro ao ler flag nova_repertorio', e); }
    };
    lerFlagRep();
    return () => { mounted = false; };
  }, []));

  useEffect(() => { AsyncStorage.setItem('nomeUsuario', nomeUsuario); }, [nomeUsuario]);
  useEffect(() => { if (fotoUri) AsyncStorage.setItem('fotoUsuario', fotoUri); }, [fotoUri]);

  useEffect(() => {
    const user = getAuth().currentUser;
    if (!user) return;
    const userStatusRef = ref(database, 'status/' + user.uid);
    dbSet(userStatusRef, 'online');
    onDisconnect(userStatusRef).set('offline');
    return () => { dbSet(userStatusRef, 'offline'); };
  }, []);

  useEffect(() => {
    const statusRef = ref(database, 'status');
    const unsubscribe = onValue(statusRef, (snapshot) => {
      const uids: string[] = [];
      snapshot.forEach(child => { if (child.val() === 'online') uids.push(child.key as string); });
      setOnlineUids(uids);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    async function buscarFotosUsuarios() {
      const presencaSnap = await getDocs(collection(db, 'presencas'));
      if (!presencaSnap.empty) {
        const presencaDoc = presencaSnap.docs[0];
        const fotosUsuarios = presencaDoc.data().fotosUsuarios || {};
        const fotos: { [uid: string]: string } = {};
        Object.entries(UID_TO_NOME).forEach(([uid, nome]) => { if (fotosUsuarios[nome]) fotos[uid] = fotosUsuarios[nome]; });
        setFotosPorUid(fotos);
      }
    }
    buscarFotosUsuarios();

    const metaRef = doc(db, 'meta', 'escalas');
    const unsub = onSnapshot(metaRef, snapshot => {
      const data = snapshot.data();
      setNovaEscalaCount(data?.newCount ? Number(data.newCount) : 0);
    });

    const metaRepRef = doc(db, 'meta', 'repertorios');
    const unsubRep = onSnapshot(metaRepRef, snapshot => {
      const data = snapshot.data();
      setNovaRepertorioCount(data?.newCount ? Number(data.newCount) : 0);
    });

    return () => { unsub(); unsubRep(); };
  }, []);

  const obterMillisCriacao = (valor: any): number => {
    const criadoEm = valor?.criadoEm || valor?.createdAt || valor?.dataCriacao || valor?.updatedAt;
    if (!criadoEm) return 0;
    if (typeof criadoEm.toMillis === 'function') return criadoEm.toMillis();
    if (criadoEm instanceof Date) return criadoEm.getTime();
    if (typeof criadoEm === 'number') return criadoEm;
    const parsed = Date.parse(criadoEm);
    return Number.isNaN(parsed) ? 0 : parsed;
  };

  const chaveUltimaLeitura = (rota: string) => `inicio_ultima_leitura_${rota}`;

  useEffect(() => {
    const unsubscribers = Object.entries(COLECOES_NOVIDADES).map(([rota, nomeColecao]) => {
      return onSnapshot(collection(db, nomeColecao), async snapshot => {
        const tempos = snapshot.docs
          .map(item => obterMillisCriacao(item.data()))
          .filter(Boolean);
        const maiorCriacao = tempos.length ? Math.max(...tempos) : Date.now();
        const storageKey = chaveUltimaLeitura(rota);
        const ultimoSalvo = await AsyncStorage.getItem(storageKey);

        if (!ultimoSalvo) {
          await AsyncStorage.setItem(storageKey, String(maiorCriacao));
          setNovidadesCards(prev => ({ ...prev, [rota]: 0 }));
          return;
        }

        const ultimo = Number(ultimoSalvo) || 0;
        const quantidade = tempos.filter(tempo => tempo > ultimo).length;
        setNovidadesCards(prev => ({ ...prev, [rota]: quantidade }));
      });
    });

    return () => unsubscribers.forEach(unsub => unsub());
  }, []);

  useEffect(() => {
    if (novaEscalaCount > 0) {
      Animated.loop(Animated.sequence([
        Animated.timing(blinkOpacity, { toValue: 0.3, duration: 500, useNativeDriver: true }),
        Animated.timing(blinkOpacity, { toValue: 1, duration: 500, useNativeDriver: true }),
      ]), { iterations: 4 }).start();
    }
  }, [novaEscalaCount]);

  useEffect(() => {
    if (novaRepertorioCount > 0) {
      Animated.loop(Animated.sequence([
        Animated.timing(blinkOpacityRep, { toValue: 0.3, duration: 500, useNativeDriver: true }),
        Animated.timing(blinkOpacityRep, { toValue: 1, duration: 500, useNativeDriver: true }),
      ]), { iterations: 4 }).start();
    }
  }, [novaRepertorioCount]);

  const totalNovidadesCards =
    novaEscalaCount +
    novaRepertorioCount +
    Object.values(novidadesCards).reduce((total, valor) => total + valor, 0);

  useEffect(() => {
    if (totalNovidadesCards <= 0) {
      cardPulse.stopAnimation();
      cardPulse.setValue(1);
      return;
    }

    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(cardPulse, { toValue: 1.18, duration: 420, useNativeDriver: true }),
        Animated.spring(cardPulse, { toValue: 1, friction: 3, tension: 90, useNativeDriver: true }),
        Animated.delay(550),
      ])
    );
    loop.start();
    return () => loop.stop();
  }, [totalNovidadesCards, cardPulse]);

  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        if (novaEscalaCount > 0) {
          await Notifications.setBadgeCountAsync(1);
          notifEscalaRef.current = await Notifications.scheduleNotificationAsync({
            content: { title: 'Nova Escala', body: novaEscalaCount > 1 ? `${novaEscalaCount} novas escalas` : 'Uma nova escala disponível', badge: 1 },
            trigger: null,
          });
        } else if (notifEscalaRef.current) {
          await Notifications.dismissNotificationAsync(notifEscalaRef.current);
          notifEscalaRef.current = null;
        }
      } catch (e) { console.log('Erro notificação escala', e); }
    })();
    return () => { mounted = false; };
  }, [novaEscalaCount]);

  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        if (novaRepertorioCount > 0) {
          await Notifications.setBadgeCountAsync(1);
          notifRepRef.current = await Notifications.scheduleNotificationAsync({
            content: { title: 'Novo Repertório', body: novaRepertorioCount > 1 ? `${novaRepertorioCount} novos repertórios` : 'Um novo repertório disponível', badge: 1 },
            trigger: null,
          });
        } else if (notifRepRef.current) {
          await Notifications.dismissNotificationAsync(notifRepRef.current);
          notifRepRef.current = null;
        }
      } catch (e) { console.log('Erro notificação repertório', e); }
    })();
    return () => { mounted = false; };
  }, [novaRepertorioCount]);

  async function escolherFoto() {
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images, 
      allowsEditing: true, 
      aspect: [1, 1], 
      quality: 0.8,
    });
    if (!result.canceled && result.assets?.length) setFotoUri(result.assets[0].uri);
  }

  async function limparNovidadeCard(rota: string) {
    if (rota === 'Repertorios') {
      setNovaRepertorioCount(0);
      await AsyncStorage.removeItem('nova_repertorio');
      await setDoc(doc(db, 'meta', 'repertorios'), { newCount: 0, lastClearedAt: new Date(), lastClearedBy: getAuth().currentUser?.uid || null }, { merge: true });
      return;
    }

    if (rota === 'Escalas') {
      setNovaEscalaCount(0);
      await AsyncStorage.removeItem('nova_escala');
      await setDoc(doc(db, 'meta', 'escalas'), { newCount: 0, lastClearedAt: new Date(), lastClearedBy: getAuth().currentUser?.uid || null }, { merge: true });
      return;
    }

    if (COLECOES_NOVIDADES[rota as RotaComNovidade]) {
      await AsyncStorage.setItem(chaveUltimaLeitura(rota), String(Date.now()));
      setNovidadesCards(prev => ({ ...prev, [rota]: 0 }));
    }
  }

  function obterQuantidadeNovidade(rota: string) {
    if (rota === 'Repertorios') return novaRepertorioCount;
    if (rota === 'Escalas') return novaEscalaCount;
    return novidadesCards[rota] || 0;
  }

  function irPara<T extends keyof ListaRotasPrincipais>(rota: T, params?: ListaRotasPrincipais[T]) {
    void limparNovidadeCard(String(rota)).catch(error => console.log('Erro ao limpar novidade do card:', error));
    navegacao.navigate(rota, params);
  }

  async function deslogar() {
    try {
      await signOut(getAuth());
      navegacao.reset({ index: 0, routes: [{ name: 'Login' as any }] });
    } catch { Alert.alert('Erro', 'Não foi possível sair da conta.'); }
  }

  const cliqueAvatar = (uid: string) => {
    const nome = UID_TO_NOME[uid] || 'Usuário desconhecido';
    setNomeSelecionado(nome);
    setTimeout(() => setNomeSelecionado(null), 3000);
  };

  const cardWidth = (width * 0.92 - 32) / 2;

  return (
    <KeyboardAvoidingView
      style={{ flex: 1 }}
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
    >
      <StatusBar translucent backgroundColor="transparent" barStyle="light-content" />
      <LinearGradient colors={FUNDO_GRADIENT} style={estilos.fundo}>
        <SafeAreaView style={estilos.areaSegura}>
          <TouchableOpacity style={estilos.botaoSairTopo} onPress={deslogar}>
            <Feather name="log-out" size={18} color="#fff" />
            <Text style={estilos.textoSairTopo}>Sair</Text>
          </TouchableOpacity>

          <ScrollView 
            contentContainerStyle={estilos.scroll} 
            showsVerticalScrollIndicator={false}
          >
            <View style={estilos.perfil}>
              <TouchableWithoutFeedback onPress={escolherFoto}>
                <View style={estilos.fotoBorda}>
                  <LinearGradient colors={['#FF9A3C', '#FF6B00']} style={estilos.fotoGradiente}>
                    {fotoUri ? (
                      <Image source={{ uri: fotoUri }} style={estilos.foto} />
                    ) : (
                      <View style={[estilos.foto, estilos.fotoVazia]}>
                        <Svg width={52} height={52} viewBox="0 0 48 48">
                          <Circle cx="24" cy="18" r="10" fill="#6B7280" />
                          <Rect x="8" y="32" width="32" height="12" rx="6" fill="#6B7280" />
                        </Svg>
                      </View>
                    )}
                  </LinearGradient>
                  <View style={estilos.iconeEditar}>
                    <LinearGradient colors={['#FF9A3C', '#FF6B00']} style={estilos.iconeEditarGradiente}>
                      <Svg width={16} height={16} viewBox="0 0 24 24">
                        <Path d="M3 17.25V21h3.75l11.06-11.06-3.75-3.75L3 17.25z" fill="#fff"/>
                        <Path d="M20.71 7.04a1 1 0 0 0 0-1.41l-2.34-2.34a1 1 0 0 0-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z" fill="#fff"/>
                      </Svg>
                    </LinearGradient>
                  </View>
                </View>
              </TouchableWithoutFeedback>

              {!nomeEditando ? (
                <TouchableOpacity style={estilos.saudacaoContainer} onPress={() => setNomeEditando(true)}>
                  <Text style={estilos.saudacao}>Olá, {nomeUsuario || 'Digite seu nome'}! </Text>
                  <Feather name="edit-2" size={16} color={COR_DESTAQUE} style={{ marginLeft: 6 }} />
                </TouchableOpacity>
              ) : (
                <View style={estilos.edicaoNomeContainer}>
                  <TextInput
                    style={estilos.inputNome}
                    value={nomeTemporario}
                    onChangeText={setNomeTemporario}
                    placeholder="Digite seu nome completo"
                    placeholderTextColor="#9CA3AF"
                    autoFocus
                    maxLength={40}
                    onSubmitEditing={salvarNome}
                  />
                  <View style={estilos.botoesEdicao}>
                    <TouchableOpacity style={estilos.botaoSalvar} onPress={salvarNome}>
                      <Feather name="check" size={16} color="#fff" />
                    </TouchableOpacity>
                    <TouchableOpacity style={estilos.botaoCancelar} onPress={cancelarEdicaoNome}>
                      <Feather name="x" size={16} color="#fff" />
                    </TouchableOpacity>
                  </View>
                </View>
              )}
            </View>

            <View style={estilos.online}>
              <Text style={estilos.textoOnline}>Online Agora</Text>
              {nomeSelecionado && (
                <View style={estilos.caixaNome}>
                  <Text style={estilos.textoNome}>{nomeSelecionado}</Text>
                </View>
              )}
              <View style={estilos.listaOnline}>
                {onlineUids.length > 0 ? (
                  onlineUids.map(uid => (
                    <TouchableOpacity key={uid} style={estilos.avatarOnline} onPress={() => cliqueAvatar(uid)}>
                      {fotosPorUid[uid] ? (
                        <Image source={{ uri: fotosPorUid[uid] }} style={estilos.fotoOnline} />
                      ) : (
                        <MaterialCommunityIcons name="account-circle" size={34} color={COR_SUCESSO} />
                      )}
                    </TouchableOpacity>
                  ))
                ) : (
                  <Text style={estilos.semOnline}>Ninguém online no momento</Text>
                )}
              </View>
            </View>

            <View style={estilos.grade}>
              {botoes.map((btn) => {
                const quantidadeNovidade = obterQuantidadeNovidade(btn.rota);
                const temNovidade = quantidadeNovidade > 0;
                const badgeOpacity = btn.rota === 'Repertorios'
                  ? blinkOpacityRep
                  : btn.rota === 'Escalas'
                    ? blinkOpacity
                    : cardPulse.interpolate({ inputRange: [1, 1.18], outputRange: [0.72, 1] });

                return (
                  <NeumorphicButton
                    key={btn.titulo}
                    style={[estilos.card, temNovidade && estilos.cardComNovidade, { width: cardWidth }]}
                    onPress={() => irPara(btn.rota as any)}
                  >
                    <LinearGradient colors={BUTTON_GRADIENT} style={estilos.cardGradiente}>
                      <View style={estilos.iconeContainer}>
                        <Animated.View style={temNovidade ? [estilos.iconeAnimado, { transform: [{ scale: cardPulse }] }] : undefined}>
                          {btn.icone}
                        </Animated.View>
                        {temNovidade && (
                          <Animated.View style={[estilos.badge, { opacity: badgeOpacity }]}>
                            <Text style={estilos.textoBadge}>{quantidadeNovidade > 99 ? '99+' : quantidadeNovidade}</Text>
                          </Animated.View>
                        )}
                      </View>
                      <Text style={estilos.textoCard}>{btn.titulo}</Text>
                    </LinearGradient>
                  </NeumorphicButton>
                );
              })}
            </View>
          </ScrollView>
        </SafeAreaView>
      </LinearGradient>
    </KeyboardAvoidingView>
  );
}

